import torchimport torch.nn as nnimport torch.nn.functional as Fclass Rasch_Embedding(nn.Module):    def __init__(self, n_exercise, n_concept, Q_matrix, embedding_dim):        super().__init__()        self.exer_emb = nn.Embedding(n_exercise, embedding_dim)        self.exer_lam = nn.Embedding(n_exercise, 1)        self.concept_emb = nn.Embedding(n_concept, embedding_dim)        self.Q_matrix = Q_matrix    def forward(self, exercise):        exer_embedding = self.exer_emb(exercise)  # (n_exer, embedding_dim)        exer_lambda = self.exer_lam(exercise)  # (n_exer, 1)        related_concepts = self.Q_matrix[exercise]  # (n_exer, n_concept)        concept_embedding_sum = torch.matmul(related_concepts, self.concept_emb.weight)  # (n_exer, embedding_dim)        concept_count = torch.sum(related_concepts, dim=1, keepdim=True)  # (n_exer, 1)        concept_embedding = concept_embedding_sum / concept_count  # (n_exer, embedding_dim)        rasch_embedding = exer_embedding + exer_lambda * concept_embedding        return rasch_embeddingclass AttentionBlock(nn.Module):    def __init__(self, in_features, out_features, num_heads=4):        super().__init__()        assert out_features % num_heads == 0        self.out_features = out_features // num_heads        self.num_heads = num_heads        self.W_v = nn.Linear(in_features, out_features)  # (in_features) -> (out_features)        self.W_q = nn.Linear(in_features, out_features)  # (in_features) -> (out_features)        self.W_k = nn.Linear(in_features, out_features)  # (in_features) -> (out_features)    def forward(self, q, k, v, mask=None):        mapped_v = self.W_v(v).reshape(v.size(0), -1, self.num_heads, self.out_features).permute(2, 0, 1, 3)        mapped_q = self.W_q(q).reshape(q.size(0), -1, self.num_heads, self.out_features).permute(2, 0, 1, 3)        mapped_k = self.W_k(k).reshape(k.size(0), -1, self.num_heads, self.out_features).permute(2, 0, 1, 3)        attn_score = torch.matmul(mapped_q, mapped_k.transpose(-1, -2)) / (self.out_features ** 0.5)        if mask is not None:            expanded_mask = mask.unsqueeze(1) & mask.unsqueeze(2)            expanded_mask = expanded_mask.unsqueeze(0)            attn_score = attn_score.masked_fill(~expanded_mask, float('-inf'))        attention = F.softmax(attn_score, dim=-1)        attention = attention.masked_fill(~expanded_mask, 0)        out = torch.matmul(attention, mapped_v).permute(1, 2, 0, 3).reshape(v.size(0), -1,                                                                            self.num_heads * self.out_features)        return outclass AttentionEncoder_tree(nn.Module):    def __init__(self, n_exercise, out_dim, n_concept=None, embedding_dim=128, out_sigmoid=True, block_num=1,                 pooling="mean", q_matrix=None, concept_tree=None):        super().__init__()        if n_concept is None:            n_concept = out_dim // 2        self.embedding_dim = embedding_dim        # self.exercise_embedding = nn.Embedding(n_exercise, embedding_dim)        self.exercise_embedding = Rasch_Embedding(n_exercise, n_concept, q_matrix, embedding_dim)        self.response_embedding = nn.Embedding(3, embedding_dim)        self.attention_block = AttentionBlock(embedding_dim, embedding_dim)        self.attention_blocks = self.model_blocks = nn.ModuleList(            [AttentionBlock(embedding_dim, embedding_dim) for _ in range(block_num)])        self.er_linear = nn.Linear(2 * embedding_dim, embedding_dim)        if out_sigmoid:            self.map_layer = nn.Sequential(                nn.Linear(embedding_dim, 1),                nn.Sigmoid()            )        else:            self.map_layer = nn.Linear(embedding_dim, 1)        self.pooling = pooling        self.q_matrix = q_matrix        self.concept_tree = concept_tree        self.node_mask = self.prepare_tree(concept_tree).cuda()        self.n_node, self.n_leaf = self.node_mask.shape        self.node_depth = self.extract_node_depth_tensor(concept_tree).cuda()        self.num_levels = int(self.node_depth.max().item()) + 1        if out_sigmoid:            self.level_mlps = nn.ModuleList([                nn.Sequential(                    nn.Linear(embedding_dim, 1),                    nn.Sigmoid()                )                for _ in range(self.num_levels)            ])        else:            self.level_mlps = nn.ModuleList([                nn.Linear(embedding_dim, 1)                for _ in range(self.num_levels)            ])    def forward(self, p_matrix):        batch_size = p_matrix.shape[0]        non_zero_indices = torch.nonzero(p_matrix).cuda()        non_zero_count_per_sample = non_zero_indices[:, 0].bincount(minlength=p_matrix.shape[0])        max_non_zero_count = non_zero_count_per_sample.max().item()        padded_exercise_embed = torch.zeros((p_matrix.shape[0], max_non_zero_count, self.embedding_dim)).cuda()        padded_response_embed = torch.zeros((p_matrix.shape[0], max_non_zero_count, self.embedding_dim)).cuda()        padded_er_embed = torch.zeros((p_matrix.shape[0], max_non_zero_count, self.embedding_dim)).cuda()        exercise_idx = non_zero_indices[:, 1]        response_idx = p_matrix[non_zero_indices[:, 0], exercise_idx]        exercise_embed = self.exercise_embedding(exercise_idx)  # (num_nonzero, embedding_dim)        response_embed = self.response_embedding(response_idx.to(torch.int))  # (num_nonzero, embedding_dim)        er_embed = self.er_linear(torch.concatenate([exercise_embed, response_embed], dim=1))        student_idx = non_zero_indices[:, 0]        position_idx = torch.cat([torch.arange(count, device=p_matrix.device) for count in non_zero_count_per_sample])        padded_exercise_embed[student_idx, position_idx] = exercise_embed        padded_response_embed[student_idx, position_idx] = response_embed        padded_er_embed[student_idx, position_idx] = er_embed        mask = ((torch.arange(max_non_zero_count).expand(p_matrix.shape[0],                                                         max_non_zero_count).cuda() < non_zero_count_per_sample.unsqueeze(            1)))        theta = self.attention_block(padded_response_embed, padded_exercise_embed, padded_response_embed, mask)        if len(self.attention_blocks) > 1:            for attention_block in self.attention_blocks[1:]:                theta = attention_block(theta, theta, theta, mask)        if self.pooling == "mean":            theta = self.pool_by_concept_tree(self.q_matrix, exercise_idx, theta, mask, self.node_mask)        # 聚合结果        theta = self.map_layer(theta).squeeze(-1)        return theta    def prepare_tree(self, final_tree):        leaf_ids = []        def collect_leaves(node):            if not node.get("children"):                leaf_ids.append(node["id"])            else:                for c in node["children"]:                    collect_leaves(c)        collect_leaves(final_tree)        leaf_ids = sorted(set(leaf_ids))        max_leaf_id = max(leaf_ids)        node_ids = []        def collect_nodes(node):            node_ids.append(node["id"])            for c in node.get("children", []):                collect_nodes(c)        collect_nodes(final_tree)        node_ids = sorted(set(node_ids))        max_node_id = max(node_ids)        node_mask = torch.zeros(max_node_id + 1, max_leaf_id + 1, dtype=torch.bool)        def fill_mask(node):            if not node.get("children"):                node_mask[node["id"], node["id"]] = True                return {node["id"]}            else:                leaves = set()                for c in node["children"]:                    leaves |= fill_mask(c)                for l in leaves:                    node_mask[node["id"], l] = True                return leaves        fill_mask(final_tree)        return node_mask    def extract_node_depth_tensor(self, final_tree):        node_depth_dict = {}        def dfs(node, depth):            node_depth_dict[node["id"]] = depth            for c in node.get("children", []):                dfs(c, depth + 1)        dfs(final_tree, depth=0)        max_node_id = max(node_depth_dict.keys())        node_depth = torch.zeros(max_node_id + 1, dtype=torch.long)        for nid, d in node_depth_dict.items():            node_depth[nid] = d        return node_depth    def pool_by_concept_tree(self, Q, exercise_idx, theta, mask, node_mask):        device = theta.device        B, L, d = theta.shape        n_node, n_leaf = node_mask.shape        # leaf_repr: (B, n_leaf, d)        leaf_repr = pool_by_concept_vectorized(Q, exercise_idx, theta, mask)        # node_mask_float: (n_node, n_leaf)        node_mask_float = node_mask.float()        node_mask_float = node_mask_float / node_mask_float.sum(dim=1, keepdim=True).clamp(min=1e-6)        node_mask_batch = node_mask_float.unsqueeze(0).expand(B, -1, -1)        node_repr = torch.bmm(node_mask_batch, leaf_repr)  # (B, n_node, d)        return node_repr    def pool_by_concept_tree_new(            self,            Q,            exercise_idx,            theta,            mask,            node_mask,    ):        """        Q: (n_q, n_leaf)        exercise_idx: (N_total,)        theta: (B, L, d)        mask: (B, L)        node_mask: (n_node, n_leaf) bool        return: (B, n_node, d)        """        device = theta.device        B, L, d = theta.shape        n_node, n_leaf = node_mask.shape        # -----------------------        # Lazy init learnable weights        # -----------------------        if not hasattr(self, "node_leaf_weight"):            self.node_leaf_weight = torch.nn.Parameter(                torch.zeros(n_node, n_leaf, device=device)            )        leaf_repr = pool_by_concept_vectorized(            Q, exercise_idx, theta, mask        )  # (B, n_leaf, d)        node_mask_float = node_mask.float()  # (n_node, n_leaf)        masked_weight = self.node_leaf_weight.masked_fill(            node_mask_float == 0, float("-inf")        )        # 对每个父节点的子叶子做 softmax        attn = torch.softmax(masked_weight, dim=1)  # (n_node, n_leaf)        # batch expand        attn_batch = attn.unsqueeze(0).expand(B, -1, -1)  # (B, n_node, n_leaf)        # 聚合        node_repr = torch.bmm(attn_batch, leaf_repr)  # (B, n_node, d)        return node_reprdef pool_by_concept_vectorized(Q, exercise_idx_flat, theta, mask):    """    Q: (n_q, n_c)    exercise_idx_flat: (N_total,)    theta: (B, L, d)    mask: (B, L)    return: (B, n_c, d)    """    device = theta.device    B, L, d = theta.shape    n_q, n_c = Q.shape    mask_flat = mask.reshape(-1)  # (B*L,)    valid_pos = torch.nonzero(mask_flat, as_tuple=True)[0]    ex_idx_mat = torch.zeros(B * L, dtype=torch.long, device=device)    ex_idx_mat[valid_pos] = exercise_idx_flat.to(device)    ex_idx_mat = ex_idx_mat.reshape(B, L)  # (B, L)    ex_q = Q[ex_idx_mat]  # (B, L, n_c)    ex_q = ex_q * mask.unsqueeze(-1).float()  # (B, L, n_c)    # theta: (B, L, d) → (B, L, 1, d)    theta_expanded = theta.unsqueeze(2)  # (B, L, 1, d)    # ex_q: (B, L, n_c) → (B, L, n_c, 1)    ex_q_expanded = ex_q.unsqueeze(-1)  # (B, L, n_c, 1)    masked_theta = theta_expanded * ex_q_expanded  # (B, L, n_c, d)    kc_sum = masked_theta.sum(dim=1)  # (B, n_c, d)    kc_count = ex_q.sum(dim=1).unsqueeze(-1)  # (B, n_c, 1)    kc_count = kc_count.clamp(min=1)    student_kc_repr = kc_sum / kc_count  # (B, n_c, d)    return student_kc_repr